-- Generated by RoPorter
RoPorterCatalog = RoPorterCatalog or {}
RoPorterCatalog[ "models/player/roporter/thenoobofficial_r.mdl" ] = { name = "TheNoobOfficial_R", type = "Avatars" }

hook.Add( "PopulatePropMenu", "RoPorterItems", function()
	local items = {}
	for model, name in pairs( RoPorterItems or {} ) do items[ model ] = { name = name, type = "Other" } end
	for model, item in pairs( RoPorterCatalog ) do items[ model ] = item end
	local types = {}
	for model, item in pairs( items ) do
		types[ item.type ] = types[ item.type ] or {}
		table.insert( types[ item.type ], model )
	end
	spawnmenu.AddPropCategory( "RoPorterItems", "RoPorter", {}, "roporter/spawnmenu/roporter.png", 7672767, 0 )
	for name, models in SortedPairs( types ) do
		table.sort( models, function( a, b ) return items[ a ].name:lower() < items[ b ].name:lower() end )
		local contents = {}
		for _, model in ipairs( models ) do contents[ #contents + 1 ] = { type = "model", model = model } end
		local icon = name == "Avatars" and "roporter/spawnmenu/avatars.png" or name == "Bundles" and "roporter/spawnmenu/bundles.png"
			or name == "Models" and "roporter/spawnmenu/models.png" or "roporter/spawnmenu/catalog.png"
		spawnmenu.AddPropCategory( "RoPorterItems/" .. name, name, contents, icon,
			7672768 + tonumber( util.CRC( name ) ) % 1000000, 7672767 )
	end
end )
